#!/bin/sh
# Code generated by honey. DO NOT EDIT.
# Installs anyrow on Linux or macOS: the archive for this OS and architecture, its sha256 checked against
# checksums.txt, and checksums.txt's signature by cosign when it is installed, before anything installs. The script
# is one function called on its last line, so a truncated download runs nothing.
#   ANYROW_VERSION         a release tag (default: the latest)
#   ANYROW_INSTALL_BASE    where the release's files are: https://, or http:// on loopback
#   ANYROW_INSTALL_DIR     where anyrow goes (default: ~/.local/bin)
#   ANYROW_INSTALL_ARCH    amd64 or arm64, over this machine's
#   ANYROW_INSTALL_VERIFY  require: refuse to install unless cosign checks the signature
set -eu

fail() {
	echo "anyrow install: $1" >&2
	exit 1
}

# fetch <url> <file>: curl or wget, held to https (or http on a loopback base)
fetch() {
	if command -v curl >/dev/null 2>&1; then
		curl --proto "$proto" --tlsv1.2 -fsSL -o "$2" "$1" || fail "could not download $1"
	elif command -v wget >/dev/null 2>&1; then
		if [ "$proto" = "=https" ]; then
			wget --https-only -q -O "$2" "$1" || fail "could not download $1"
		else
			wget -q -O "$2" "$1" || fail "could not download $1"
		fi
	else
		fail "neither curl nor wget is installed"
	fi
}

# sha256 <file>: its digest, by sha256sum or shasum
sha256() {
	if command -v sha256sum >/dev/null 2>&1; then
		sha256sum "$1" | awk '{ print $1 }'
	elif command -v shasum >/dev/null 2>&1; then
		shasum -a 256 "$1" | awk '{ print $1 }'
	else
		fail "neither sha256sum nor shasum is installed to verify the download"
	fi
}

# resolve_base: where the release's files are, its protocol checked before any fetch
resolve_base() {
	if [ -n "${ANYROW_INSTALL_BASE:-}" ]; then
		base=${ANYROW_INSTALL_BASE}
	elif [ -z "$repo" ]; then
		fail "set ANYROW_INSTALL_BASE: no repository to download from"
	elif [ -n "${ANYROW_VERSION:-}" ]; then
		case ${ANYROW_VERSION} in
		*[!A-Za-z0-9._-]* | .* | "") fail "ANYROW_VERSION ${ANYROW_VERSION}: not a release tag" ;;
		esac
		base="https://github.com/$repo/releases/download/${ANYROW_VERSION}"
	else
		base="https://github.com/$repo/releases/latest/download"
	fi
	case $base in
	https://*)
		proto="=https"
		return
		;;
	http://*) ;;
	*) fail "$base: want https://" ;;
	esac
	rest=${base#http://}
	case $rest in
	\[::1\] | \[::1\][:/]*) host="[::1]" ;;
	*)
		host=${rest%%/*}
		host=${host%%:*}
		;;
	esac
	case $host in
	localhost | "[::1]") ;;
	127.*)
		case $host in
		*[!0-9.]*) fail "$base: want https://" ;;
		esac
		;;
	*) fail "$base: want https://, or http:// on loopback" ;;
	esac
	proto="=http"
}

# platform: the archive's os and arch
platform() {
	case $(uname -s) in
	Linux) os=linux ;;
	Darwin) os=darwin ;;
	*) fail "$(uname -s): this script installs on Linux and macOS; on Windows, run install.ps1" ;;
	esac
	arch=${ANYROW_INSTALL_ARCH:-}
	if [ -z "$arch" ]; then
		case $(uname -m) in
		x86_64 | amd64) arch=amd64 ;;
		aarch64 | arm64) arch=arm64 ;;
		*) fail "$(uname -m): no build for this architecture (set ANYROW_INSTALL_ARCH to amd64 or arm64)" ;;
		esac
	fi
	case $arch in
	amd64 | arm64) ;;
	*) fail "ANYROW_INSTALL_ARCH $arch: want amd64 or arm64" ;;
	esac
}

# signer: cosign when it checks checksums.txt's signature (on PATH, a repository naming the signer), refused
# before any fetch when ANYROW_INSTALL_VERIFY=require and it cannot
signer() {
	case ${ANYROW_INSTALL_VERIFY:-} in
	"" | require) ;;
	*) fail "ANYROW_INSTALL_VERIFY ${ANYROW_INSTALL_VERIFY}: want require, or unset" ;;
	esac
	signer=
	if [ -z "$identity" ]; then
		why="no repository names who signs checksums.txt"
	elif command -v cosign >/dev/null 2>&1; then
		signer=cosign
	else
		why="cosign is not installed to verify checksums.txt's signature"
	fi
	[ -n "$signer" ] || [ "${ANYROW_INSTALL_VERIFY:-}" != require ] || fail "ANYROW_INSTALL_VERIFY=require: $why"
}

# verify: checksums.txt's bundle checked by cosign as the release workflow's on a v* tag
verify() {
	fetch "$base/checksums.txt.sigstore.json" "$tmp/checksums.txt.sigstore.json"
	cosign verify-blob --bundle "$tmp/checksums.txt.sigstore.json" --certificate-identity-regexp "$identity" \
		--certificate-oidc-issuer https://token.actions.githubusercontent.com "$tmp/checksums.txt" >/dev/null 2>&1 ||
		fail "checksums.txt: cosign could not verify it as signed by $repo's release workflow"
}

main() {
	bin='anyrow'
	repo='anyrow/cli'
	identity='(?i)^https://github\.com/anyrow/cli/\.github/workflows/release\.yml@refs/tags/v'
	resolve_base
	platform
	signer
	archive="${bin}_${os}_${arch}.tar.gz"
	dir=${ANYROW_INSTALL_DIR:-$HOME/.local/bin}
	tmp=$(mktemp -d)
	trap 'rm -rf "$tmp"' EXIT
	fetch "$base/$archive" "$tmp/$archive"
	fetch "$base/checksums.txt" "$tmp/checksums.txt"
	[ -z "$signer" ] || verify
	want=$(awk -v name="$archive" '$2 == name { print $1 }' "$tmp/checksums.txt")
	[ -n "$want" ] || fail "checksums.txt lists no $archive"
	got=$(sha256 "$tmp/$archive")
	[ "$got" = "$want" ] || fail "$archive: its sha256 is $got, checksums.txt says $want"
	mkdir "$tmp/x"
	tar -xzf "$tmp/$archive" -C "$tmp/x" "$bin" || fail "$archive holds no $bin"
	mkdir -p "$dir"
	cp "$tmp/x/$bin" "$dir/.$bin.new"
	chmod 755 "$dir/.$bin.new"
	mv -f "$dir/.$bin.new" "$dir/$bin"
	echo "installed $dir/$bin"
}

main "$@"
